mapper.select:
SELECT ID, ISSUE_ID FROM QUALITY_ISSUE_INFO WHERE DEL_FLAG = 0 AND ID IN
#{id}
ORDER BY ID

mapper.update:
UPDATE QUALITY_ISSUE SET STATUS = '2', UPDATE_TIME = CURRENT_TIMESTAMP,
    UPDATER_ID = #{userId}, UPDATE_BY = #{userName}
WHERE ID = #{id} AND DEL_FLAG = 0 AND STATUS IN ('1', '2')

UPDATE QUALITY_ISSUE_TASK
SET STATUS = #{targetStatus}, UPDATE_TIME = #{updateTime},
    UPDATER_ID = #{updaterId}, UPDATE_BY = #{updateBy}
WHERE ID = #{id} AND DEL_FLAG = 0 AND STATUS = #{expectedStatus}

mapper.sql:
t.DEL_FLAG = 0
AND t.ID = #{req.id}

    AND t.ID IN
    #{taskId}

AND t.MODEL_ID = #{req.modelId}
AND t.ASSIGNEE_ID = #{req.assigneeId}
AND t.PRIORITY = #{req.priority}
AND t.STATUS = #{req.status}

    AND INSTR(LOWER(t.TASK_NO), LOWER(#{req.taskNo})) > 0


    AND EXISTS (
        SELECT 1 FROM QUALITY_ISSUE_TASK_INFO d
        WHERE d.TASK_ID = t.ID AND d.DEL_FLAG = 0
        AND d.ISSUE_ID = #{req.issueId}
        AND d.QUALITY_RULE_ID = #{req.qualityRuleId}
        AND d.MASTER_RECORD_ID = #{req.masterRecordId}
    )

AND t.MODEL_VERSION = #{req.modelVersion}
AND t.VALID_FLAG = #{req.validFlag}
AND t.REQUIREMENT = #{req.requirement}
AND t.RECTIFICATION_TIME = #{req.rectificationTime}

    AND t.RECTIFICATION_TIME IS NOT NULL AND t.RECTIFICATION_TIME < CURRENT_TIMESTAMP


    AND (t.RECTIFICATION_TIME IS NULL OR t.RECTIFICATION_TIME >= CURRENT_TIMESTAMP)

AND t.CREATE_TIME >= #{req.beginTime}
AND t.CREATE_TIME <= #{req.endTime}

    AND INSTR(LOWER(t.TASK_NAME), LOWER(#{req.taskName})) > 0


    AND (INSTR(LOWER(t.TASK_NO), LOWER(#{req.keyword})) > 0
        OR INSTR(LOWER(t.TASK_NAME), LOWER(#{req.keyword})) > 0)

mapper.select:
SELECT DBMS_LOB.SUBSTR(SNAPSHOT_DATA, 4000, 1)
FROM MASTER_DATA_VERSION
WHERE MODEL_ID = #{modelId}
  AND MASTER_RECORD_ID = #{masterRecordId}
  AND CURRENT_FLAG = 1
